package com.ashokmart.servlet;
import com.ashokmart.model.AuthenticationResult; import com.ashokmart.service.*; import org.slf4j.*; import javax.servlet.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import java.io.IOException;
@WebServlet(urlPatterns={"/admin/products/activate","/admin/products/deactivate"}) public final class AdminProductStatusServlet extends HttpServlet { private static final Logger LOG=LoggerFactory.getLogger(AdminProductStatusServlet.class); public void doPost(HttpServletRequest req,HttpServletResponse res)throws IOException,ServletException{AuthenticationResult admin=AdminWebSupport.authenticatedAdmin(req,res);if(admin==null)return;try{long id=Long.parseLong(req.getParameter("productId"));if(id<=0)throw new NumberFormatException();boolean active=req.getServletPath().endsWith("/activate");AdminWebSupport.adminProductService(AdminWebSupport.pool(getServletContext())).setStatus(admin.userId(),id,active);AdminWebSupport.flash(req,"adminSuccess","Product "+(active?"activated":"deactivated")+" successfully.");}catch(NumberFormatException|AdminUserException e){AdminWebSupport.flash(req,"adminError",e.getMessage()==null?"Invalid product.":e.getMessage());}catch(IllegalStateException e){LOG.error("Admin product status failed",e);AdminWebSupport.flash(req,"adminError","Product status could not be changed.");}res.sendRedirect(req.getContextPath()+"/admin/products");}}
